import { makeQuestion, PLAN } from '../game/deck.ts';
import type { Difficulty, Question, Rng } from '../game/types.ts';

/**
 * Optional AI question sets, generated by Groq.
 *
 * Security model: this is a static site with no server, so there is nowhere to
 * hide a shared secret. Each player pastes their OWN free Groq key; it stays in
 * this browser (localStorage) and is sent only to api.groq.com. Nothing is
 * committed to the repository. Get a key at https://console.groq.com/keys
 */

export const GROQ_MODELS = [
  { id: 'openai/gpt-oss-120b', label: 'GPT-OSS 120B (recommended)' },
  { id: 'openai/gpt-oss-20b', label: 'GPT-OSS 20B (faster)' },
] as const;

export const DEFAULT_MODEL: string = GROQ_MODELS[0].id;

/** Models Groq has retired, mapped to a working replacement (Groq deprecations page, checked 2026-10-31). */
const RETIRED: Record<string, string> = {
  'llama-3.3-70b-versatile': 'openai/gpt-oss-120b',
  'llama-3.1-8b-instant': 'openai/gpt-oss-20b',
};

export function resolveModel(stored: string): string {
  if (!stored) return DEFAULT_MODEL;
  return RETIRED[stored] ?? stored;
}

export class GroqError extends Error {}

const LETTERS = ['A', 'B', 'C', 'D'];
const DIFFICULTIES = new Set<string>(PLAN.map((p) => p.difficulty));

export function buildPrompt(topic: string): string {
  const plan = PLAN.map((d) => `- ${d.count} questions with "difficulty": "${d.difficulty}"`).join('\n');
  const focus = topic.trim()
    ? `Focus all questions on this theme: "${topic.trim().slice(0, 80)}". Stay on-theme for every question.`
    : 'Cover a broad mix of general knowledge (history, science, geography, culture, sports, literature, art) and vary the topic from question to question.';
  return `Generate exactly 15 trivia questions for a prize-ladder quiz game, ordered from easiest to hardest.

${focus}

Difficulty distribution, in this exact order:
${plan}

Rules:
- Each question has exactly 4 options labelled "A", "B", "C", "D" and exactly one correct option.
- Every question must have a single, unambiguous, factually accurate answer. Avoid opinions and facts that change (current office-holders, live scores, records).
- Options must never refer to other options (no "both A and B").
- Keep each question under 160 characters and each option under 60 characters.
- No repeated topics or near-duplicates.
- Respond with raw JSON only, no commentary and no markdown.

JSON shape:
{"questions":[{"question":"string","options":[{"letter":"A","text":"string"},{"letter":"B","text":"string"},{"letter":"C","text":"string"},{"letter":"D","text":"string"}],"correctLetter":"A","difficulty":"easy"}]}`;
}

/** Pull a JSON object out of a model reply, tolerating code fences and stray text. */
export function extractJson(text: string): unknown {
  const t = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try {
    return JSON.parse(t);
  } catch {
    const a = t.indexOf('{');
    const b = t.lastIndexOf('}');
    if (a >= 0 && b > a) {
      try {
        return JSON.parse(t.slice(a, b + 1));
      } catch {
        /* handled below */
      }
    }
  }
  throw new GroqError('The AI reply was not valid JSON.');
}

/** Validate a model reply and turn it into a game-ready deck (shuffled answers, ladder order). */
export function normalizeQuestions(raw: unknown, rng: Rng = Math.random): Question[] {
  const list = (raw as { questions?: unknown } | null)?.questions;
  if (!Array.isArray(list)) throw new GroqError('The AI reply did not contain a questions list.');

  const parsed = list.map((q, i) => {
    const n = i + 1;
    if (!q || typeof q !== 'object') throw new GroqError(`Question ${n} is malformed.`);
    const { question, options, correctLetter, difficulty } = q as Record<string, unknown>;
    if (typeof question !== 'string' || !question.trim()) throw new GroqError(`Question ${n} has no text.`);
    if (!Array.isArray(options) || options.length !== 4) throw new GroqError(`Question ${n} needs exactly 4 options.`);
    const byLetter = new Map<string, string>();
    for (const o of options) {
      const { letter, text } = (o ?? {}) as Record<string, unknown>;
      const l = typeof letter === 'string' ? letter.toUpperCase() : '';
      if (!LETTERS.includes(l) || typeof text !== 'string' || !text.trim()) throw new GroqError(`Question ${n} has a bad option.`);
      byLetter.set(l, text.trim());
    }
    if (byLetter.size !== 4) throw new GroqError(`Question ${n} options must be A, B, C and D.`);
    const right = typeof correctLetter === 'string' ? byLetter.get(correctLetter.toUpperCase()) : undefined;
    if (!right) throw new GroqError(`Question ${n} has an invalid correct answer.`);
    if (typeof difficulty !== 'string' || !DIFFICULTIES.has(difficulty)) throw new GroqError(`Question ${n} has an invalid difficulty.`);
    const wrong = LETTERS.filter((l) => l !== String(correctLetter).toUpperCase()).map((l) => byLetter.get(l)!);
    if (new Set([right, ...wrong].map((t) => t.toLowerCase())).size !== 4) throw new GroqError(`Question ${n} repeats an answer.`);
    return { text: question.trim(), right, wrong, difficulty: difficulty as Difficulty };
  });

  const ordered = PLAN.flatMap(({ difficulty, count }) => parsed.filter((p) => p.difficulty === difficulty).slice(0, count));
  const need = PLAN.reduce((a, p) => a + p.count, 0);
  if (ordered.length !== need) throw new GroqError('The AI reply did not include 5 easy, 5 medium, 4 hard and 1 very hard question.');
  if (new Set(ordered.map((p) => p.text.toLowerCase())).size !== need) throw new GroqError('The AI repeated a question.');
  return ordered.map((p, i) => makeQuestion(i + 1, p.text, p.right, p.wrong, p.difficulty, rng));
}

interface Options {
  apiKey: string;
  model: string;
  topic: string;
  signal?: AbortSignal;
  timeoutMs?: number;
}

async function post(body: Record<string, unknown>, apiKey: string, signal: AbortSignal): Promise<Response> {
  return fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey}` },
    body: JSON.stringify(body),
    signal,
  });
}

/** Ask Groq for a fresh 15-question game. Always throws GroqError on failure so callers can fall back. */
export async function generateQuestions(opts: Options): Promise<Question[]> {
  if (!opts.apiKey) throw new GroqError('No Groq API key is set.');
  const model = resolveModel(opts.model);

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs ?? 30_000);
  const onAbort = () => controller.abort();
  opts.signal?.addEventListener('abort', onAbort);

  const messages = [
    { role: 'system', content: 'You are a trivia question writer. You always answer with a single valid JSON object and nothing else.' },
    { role: 'user', content: buildPrompt(opts.topic) },
  ];

  try {
    // First try with JSON mode and low reasoning effort. If Groq rejects an extra
    // parameter for this model (HTTP 400), retry once with the plain request.
    let res = await post(
      { model, messages, temperature: 0.8, response_format: { type: 'json_object' }, ...(model.startsWith('openai/gpt-oss') ? { reasoning_effort: 'low' } : {}) },
      opts.apiKey,
      controller.signal,
    );
    if (res.status === 400) res = await post({ model, messages, temperature: 0.8 }, opts.apiKey, controller.signal);

    if (!res.ok) {
      let detail = '';
      try {
        detail = ((await res.json()) as { error?: { message?: string } })?.error?.message ?? '';
      } catch {
        /* no body */
      }
      if (res.status === 401) throw new GroqError('Groq rejected the API key (401). Check that it is copied correctly.');
      if (res.status === 403) throw new GroqError('Groq refused the request (403). Your key may not have access.');
      if (res.status === 404) throw new GroqError('Groq could not find that model (404). Choose another model in Settings.');
      if (res.status === 429) throw new GroqError('Groq rate limit reached (429). Try again in a moment.');
      throw new GroqError(`Groq request failed (${res.status})${detail ? `: ${detail.slice(0, 120)}` : ''}.`);
    }

    const data = (await res.json()) as { choices?: { message?: { content?: unknown } }[] };
    const content = data?.choices?.[0]?.message?.content;
    if (typeof content !== 'string') throw new GroqError('Groq sent an empty reply.');
    return normalizeQuestions(extractJson(content));
  } catch (err) {
    if (err instanceof GroqError) throw err;
    if (opts.signal?.aborted) throw err;
    if (controller.signal.aborted) throw new GroqError('Groq took too long to answer.');
    throw new GroqError(navigator.onLine === false ? 'You are offline.' : 'Could not reach Groq.');
  } finally {
    clearTimeout(timer);
    opts.signal?.removeEventListener('abort', onAbort);
  }
}
